517: fn collect_sites(root: &Node, function_index: Option<usize>, provenance: &mut SourceProvenance,
518:     budget: Option<DraftParseBudget>) -> Result<(), DraftError>
519: {
520:     if let Some(budget) = budget {
521:         within(DraftBudgetResource::StructuralAstDepth, budget.max_structural_ast_depth,
522:             root.depth)?;
523:         within(DraftBudgetResource::AstOccurrences, budget.max_ast_occurrences, 1)?;
524:     }
525:     let mut scheduled = 1usize;
526:     let mut todo = vec![(root, Vec::new())];
527:     while let Some((node, path)) = todo.pop() {
528:         if let Some(budget) = budget {
529:             // Before path/source clones or provenance growth. Each parsed Expr
530:             // contributes one expression site; each Pattern one pattern site.
531:             within(DraftBudgetResource::StructuralAstDepth, budget.max_structural_ast_depth,
532:                 path.len().saturating_add(1))?;
533:             within(DraftBudgetResource::AstOccurrences, budget.max_ast_occurrences,
534:                 provenance.expressions.len().saturating_add(provenance.patterns.len())
535:                     .saturating_add(1))?;
536:         }
537:         let source = SourceLocation { function_index, child_path: path.clone() };
538:         provenance.expressions.push(ExpressionSite { source: source.clone(), span: node.span,
539:             kind: node_kind(&node.expression) });
540:         for (arm_index, (span, binders)) in node.patterns.iter().enumerate() {
541:             if let Some(budget) = budget {
542:                 within(DraftBudgetResource::AstOccurrences, budget.max_ast_occurrences,
543:                     provenance.expressions.len().saturating_add(provenance.patterns.len())
544:                         .saturating_add(1))?;
545:             }
546:             provenance.patterns.push(PatternSite { match_source: source.clone(), arm_index,
547:                 span: *span, binders: binders.clone() });
548:         }
549:         for (index, child) in node.children.iter().enumerate().rev() {
550:             if let Some(budget) = budget {
551:                 within(DraftBudgetResource::StructuralAstDepth, budget.max_structural_ast_depth,
552:                     path.len().saturating_add(2))?;
553:                 within(DraftBudgetResource::AstOccurrences, budget.max_ast_occurrences,
554:                     scheduled.saturating_add(1))?;
555:             }
556:             scheduled += 1;
557:             let mut child_path = path.clone();
558:             child_path.push(index);
559:             todo.push((child, child_path));
560:         }
561:     }
562:     Ok(())

