94: fn pratt_structural_depth_differs_from_recursive_descent_depth() {
95:     let mut budget = limits();
96:     budget.max_parser_recursion_depth = 4;
97:     budget.max_structural_ast_depth = 4;
98:     assert!(parse_draft_source_bounded(&source("1 + 2 + 3 + 4"), budget).is_ok());
99:     budget.max_structural_ast_depth = 3;
100:     exceeds(&source("1 + 2 + 3 + 4"), budget,
101:         DraftBudgetResource::StructuralAstDepth, 3, 4);
102:     // Parentheses add no AST nodes or structural depth, but do recurse.
103:     budget.max_structural_ast_depth = 1;
104:     exceeds(&source("((1))"), budget,
105:         DraftBudgetResource::ParserRecursionDepth, 4, 5);
106:     budget.max_parser_recursion_depth = 6;
107:     assert!(parse_draft_source_bounded(&source("((1))"), budget).is_ok());
